// VideoServiceServer is the server API for VideoService service.
// All implementations must embed UnimplementedVideoServiceServer
// for forward compatibility.
type VideoServiceServer interface {
	// Call Management
	CreateCall(context.Context, *CreateCallRequest) (*CallSession, error)
	JoinCall(context.Context, *JoinCallRequest) (*JoinCallResponse, error)
	EndCall(context.Context, *EndCallRequest) (*emptypb.Empty, error)
	GetCall(context.Context, *GetCallRequest) (*CallSession, error)
	ListActiveCalls(context.Context, *ListActiveCallsRequest) (*ListActiveCallsResponse, error)
	// Recording
	StartRecording(context.Context, *StartRecordingRequest) (*Recording, error)
	StopRecording(context.Context, *StopRecordingRequest) (*Recording, error)
	SetRecordingConsent(context.Context, *SetRecordingConsentRequest) (*emptypb.Empty, error)
	GetRecordingConsent(context.Context, *GetRecordingConsentRequest) (*RecordingConsentStatus, error)
	ListRecordings(context.Context, *ListRecordingsRequest) (*ListRecordingsResponse, error)
	DeleteRecording(context.Context, *DeleteRecordingRequest) (*emptypb.Empty, error)
	GetRecordingDownloadURL(context.Context, *GetRecordingDownloadURLRequest) (*GetRecordingDownloadURLResponse, error)
	// Meeting Management
	CreateMeeting(context.Context, *CreateMeetingRequest) (*Meeting, error)
	GetMeeting(context.Context, *GetMeetingRequest) (*Meeting, error)
	UpdateMeeting(context.Context, *UpdateMeetingRequest) (*Meeting, error)
	DeleteMeeting(context.Context, *DeleteMeetingRequest) (*emptypb.Empty, error)
	ListMeetings(context.Context, *ListMeetingsRequest) (*ListMeetingsResponse, error)
	StartMeeting(context.Context, *StartMeetingRequest) (*StartMeetingResponse, error)
	// JoinMeeting is the idempotent participant entry point: the organizer's
	// first call starts a scheduled meeting; any invited attendee then receives
	// a LiveKit token (+ TURN ice_servers) for the in-progress room.
	JoinMeeting(context.Context, *JoinMeetingRequest) (*JoinMeetingResponse, error)
	EndMeeting(context.Context, *EndMeetingRequest) (*MeetingSummary, error)
	// GenerateMeetingSummary (Wave 7C) produces an LLM summary of the meeting's
	// public notes, persists it, and returns the updated meeting. Host/co-host only.
	GenerateMeetingSummary(context.Context, *GenerateMeetingSummaryRequest) (*Meeting, error)
	// Meeting Notes and Action Items
	SaveMeetingNotes(context.Context, *SaveMeetingNotesRequest) (*MeetingNotes, error)
	GetMeetingNotes(context.Context, *GetMeetingNotesRequest) (*MeetingNotes, error)
	GetPreviousMeetingNotes(context.Context, *GetPreviousMeetingNotesRequest) (*MeetingNotes, error)
	CreateActionItem(context.Context, *CreateActionItemRequest) (*ActionItem, error)
	UpdateActionItem(context.Context, *UpdateActionItemRequest) (*ActionItem, error)
	DeleteActionItem(context.Context, *DeleteActionItemRequest) (*emptypb.Empty, error)
	ListActionItems(context.Context, *ListActionItemsRequest) (*ListActionItemsResponse, error)
	ConvertActionItemsToTasks(context.Context, *ConvertActionItemsToTasksRequest) (*ConvertActionItemsToTasksResponse, error)
	// Meeting Chat (persisted in-call messages)
	SaveMeetingChatMessage(context.Context, *SaveMeetingChatMessageRequest) (*MeetingChatMessage, error)
	ListMeetingChatMessages(context.Context, *ListMeetingChatMessagesRequest) (*ListMeetingChatMessagesResponse, error)
	// Meeting Host Controls (Wave 3 — server-authoritative)
	PromoteCoHost(context.Context, *PromoteCoHostRequest) (*emptypb.Empty, error)
	DemoteCoHost(context.Context, *DemoteCoHostRequest) (*emptypb.Empty, error)
	ListCoHosts(context.Context, *ListCoHostsRequest) (*ListCoHostsResponse, error)
	MuteMeetingParticipant(context.Context, *MuteMeetingParticipantRequest) (*emptypb.Empty, error)
	MuteAllMeetingParticipants(context.Context, *MuteAllMeetingParticipantsRequest) (*emptypb.Empty, error)
	RemoveMeetingParticipant(context.Context, *RemoveMeetingParticipantRequest) (*emptypb.Empty, error)
	SetMeetingLock(context.Context, *SetMeetingLockRequest) (*emptypb.Empty, error)
	// Presence
	GetPresence(context.Context, *GetPresenceRequest) (*PresenceStatus, error)
	GetBulkPresence(context.Context, *GetBulkPresenceRequest) (*GetBulkPresenceResponse, error)
	SetPresenceStatus(context.Context, *SetPresenceStatusRequest) (*emptypb.Empty, error)
	UpdatePresenceConfig(context.Context, *UpdatePresenceConfigRequest) (*emptypb.Empty, error)
	GetPresenceConfig(context.Context, *GetPresenceConfigRequest) (*PresenceConfig, error)
	// Egress / auto-close callbacks (system-context only — called by webhook handler)
	CompleteRecordingByEgress(context.Context, *CompleteRecordingByEgressRequest) (*emptypb.Empty, error)
	FailRecordingByEgress(context.Context, *FailRecordingByEgressRequest) (*emptypb.Empty, error)
	CompleteMeetingByRoom(context.Context, *CompleteMeetingByRoomRequest) (*emptypb.Empty, error)
	mustEmbedUnimplementedVideoServiceServer()
}

